import{_ as t,o as r,c as o,a5 as e}from"./chunks/framework.Cooo9kuv.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"YSB0065-批量对指定文件夹下指定文件类型压缩为压缩包并删除原文件","日期":"2026-04-11T00:00:00.000Z","修改日期":"2026-04-11T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["Bat批处理"],"标签":["压缩指定类型文件","压缩文件为压缩包","批量压缩指定类型文件","批量压缩文件","文件压缩"]},"headers":[],"relativePath":"md/Bat批处理/YSB0065-批量对指定文件夹下指定文件类型压缩为压缩包并删除原文件.md","filePath":"md/Bat批处理/YSB0065-批量对指定文件夹下指定文件类型压缩为压缩包并删除原文件.md"}'),n={name:"md/Bat批处理/YSB0065-批量对指定文件夹下指定文件类型压缩为压缩包并删除原文件.md"};function s(p,a,i,l,h,_){return r(),o("div",null,[...a[0]||(a[0]=[e('<h2 id="批量对指定文件夹下指定文件类型压缩为压缩包并删除原文件" tabindex="-1">批量对指定文件夹下指定文件类型压缩为压缩包并删除原文件 <a class="header-anchor" href="#批量对指定文件夹下指定文件类型压缩为压缩包并删除原文件" aria-label="Permalink to &quot;批量对指定文件夹下指定文件类型压缩为压缩包并删除原文件&quot;">​</a></h2><p>将指定文件夹下的指定文件类型的文件进行压缩，压缩为压缩包。</p><p>用户只需要将要压缩的文件夹拖到命令行窗口中，然后输入要压缩的文件类型，如 jpg 输入格式时不需要带 . 。</p><p>程序会查找指定文件夹下的所有指定文件类型的文件，并将每个文件压缩为一个rar格式的压缩包，并保存在该文件所在的目录下，然后删除原文件。</p><p><strong>如果需要压缩其他文件类型的文件，只需重新运行脚本即可。</strong></p><h3 id="▶程序截图-可能随更新有些许变化" tabindex="-1"><strong>▶程序截图，可能随更新有些许变化</strong> <a class="header-anchor" href="#▶程序截图-可能随更新有些许变化" aria-label="Permalink to &quot;**▶程序截图，可能随更新有些许变化**&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250220165848174004192885234.png" alt=""></p><h3 id="▶【以下支持】" tabindex="-1"><strong>▶【以下支持】：</strong> <a class="header-anchor" href="#▶【以下支持】" aria-label="Permalink to &quot;**▶【以下支持】：**&quot;">​</a></h3><p>【1】、支持的文件格式：自行指定文件类型</p><p>【2】、是否支持子文件夹穿透：支持</p><h3 id="📑-使用场景例子展示" tabindex="-1">📑 使用场景例子展示 <a class="header-anchor" href="#📑-使用场景例子展示" aria-label="Permalink to &quot;📑 使用场景例子展示&quot;">​</a></h3><p>A文件夹下有很多不同类型的文件，同时有B、C、D....等文件夹，B、C、D....等这些文件夹下边还有子文件夹，子文件夹下也有文件。</p><p>【操作方法】：只需要输入A文件夹路径，然后回车键确认执行程序即可，会对A文件夹下所有指定的文件类型进行分别压缩为rar压缩包。</p><h3 id="▶-winrar程序安装说明-这步必须操作" tabindex="-1">**▶ **winrar程序安装说明，这步必须操作： <a class="header-anchor" href="#▶-winrar程序安装说明-这步必须操作" aria-label="Permalink to &quot;**▶ **winrar程序安装说明，这步必须操作：&quot;">​</a></h3><p>注意：安装路径必须为此处：D:\\rar\\，**提示：**请提前在D盘创建文件夹：rar</p><p>如果没有D盘，则安装在C盘，然后修改代码部分即可，如下所示：</p><p>将代码中的这部分代码 set &quot;rar=D:\\rar\\rar.exe&quot; 修改为 set &quot;rar=C:\\rar\\rar.exe&quot; 即可</p><h3 id="📑-bat程序下一步执行方法" tabindex="-1">📑 bat程序下一步执行方法 <a class="header-anchor" href="#📑-bat程序下一步执行方法" aria-label="Permalink to &quot;📑 bat程序下一步执行方法&quot;">​</a></h3><p>**▶ **使用时，<strong>键盘回车键（就是键盘上的 ENTER 键）</strong>“回车确认”是执行下一步的方法 ，</p><p>比如将路径复制到程序中后，回车键确认执行下一步，每一步输入后，回车键确认即可向下执行。</p><p><strong>▶ 注意：请先测试备份原文件再批量使用，以免造成不可逆损失！！！</strong></p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250220170548174004234881674.png" alt=""></p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>：建议win7及以上64位win操作系统，mac系统需要定制。</p><p><strong>注意事项：bat程序原理上是支持</strong>win32位系统的，但不能完全确定。</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：程序不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1348.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1348.html</a></p>',27)])])}const g=t(n,[["render",s]]);export{d as __pageData,g as default};
